import{_ as p,a0 as o,w as r,s as d,I as n,x as a,a1 as i,A as t,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何修復使用 Python ORM 工具 SQLAlchemy 時的常見陷阱 | LCTT x X-CMD","titleTemplate":false,"description":"如何修復使用 Python ORM 工具 SQLAlchemy 時的常見陷阱 | LCTT (201911) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何修復使用 Python ORM 工具 SQLAlchemy 時的常見陷阱 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何修復使用 Python ORM 工具 SQLAlchemy 時的常見陷阱 | LCTT (201911) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201911/20190912 How to fix common pitfalls with the Python ORM tool SQLAlchemy","title":"如何修復使用 Python ORM 工具 SQLAlchemy 時的常見陷阱","tag":"201911","desc":""},"relativePath":"201911/20190912 How to fix common pitfalls with the Python ORM tool SQLAlchemy.md","filePath":"[post].md"}'),h={name:"201911/20190912 How to fix common pitfalls with the Python ORM tool SQLAlchemy.md"};function c(u,s,g,b,k,m){const e=o("Link");return r(),d("div",null,[s[24]||(s[24]=n("h1",{id:"如何修復使用-python-orm-工具-sqlalchemy-時的常見陷阱",tabindex:"-1"},[a("如何修復使用 Python ORM 工具 SQLAlchemy 時的常見陷阱 "),n("a",{class:"header-anchor",href:"#如何修復使用-python-orm-工具-sqlalchemy-時的常見陷阱","aria-label":"Permalink to “如何修復使用 Python ORM 工具 SQLAlchemy 時的常見陷阱”"},"​")],-1)),s[25]||(s[25]=n("blockquote",null,[n("p",null,"在使用 SQLAlchemy 時，那些看似很小的選擇可能對這種對象關係映射工具包的性能產生重要影響。")],-1)),s[26]||(s[26]=n("p",null,[n("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/python_snake_file_box.jpg?itok=UuDVFLX-",alt:"A python with a package.",title:"A python with a package."})],-1)),n("p",null,[s[2]||(s[2]=n("ruby",null,[a("對象關係映射"),n("rt",null,"Object-relational mapping")],-1)),s[3]||(s[3]=a("（",-1)),i(e,{href:"https://en.wikipedia.org/wiki/Object-relational_mapping"},{default:t(()=>[...s[0]||(s[0]=[a("ORM",-1)])]),_:1}),s[4]||(s[4]=a("）使應用程序開發人員的工作更輕鬆，在很大程度是因為它允許你使用你可能知道的語言（例如 Python）與資料庫交互，而不是使用原始 SQL 語句查詢。",-1)),i(e,{href:"https://www.sqlalchemy.org/"},{default:t(()=>[...s[1]||(s[1]=[a("SQLAlchemy",-1)])]),_:1}),s[5]||(s[5]=a(" 是一個 Python ORM 工具包，它提供使用 Python 訪問 SQL 資料庫的功能。它是一個成熟的 ORM 工具，增加了模型關係、強大的查詢構造範式、簡單的序列化等優點。然而，它的易用性使得人們很容易忘記其背後發生了什麼。使用 SQLAlchemy 時做出的看似很小的選擇可能產生非常大的性能影響。",-1))]),s[27]||(s[27]=l(`<p>本文解釋了開發人員在使用 SQLAlchemy 時遇到的一些最重要的性能問題，以及如何解決這些問題。</p><h3 id="只需要計數但檢索整個結果集" tabindex="-1">只需要計數但檢索整個結果集 <a class="header-anchor" href="#只需要計數但檢索整個結果集" aria-label="Permalink to “只需要計數但檢索整個結果集”">​</a></h3><p>有時開發人員只需要一個結果計數，但是沒有使用資料庫計數功能，而是獲取了所有結果，然後使用 Python 中的 <code>len</code> 完成計數。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>count = len(User.query.filter_by(acct_active=True).all())</span></span></code></pre></div><p>相反，使用 SQLAlchemy 的 <code>count</code> 方法將在服務器端執行計數，從而減少發送到客户端的數據。在前面的例子中調用 <code>all()</code> 也會導致模型對象的實例化，如果有很多數據，那麼時間代價可能會非常昂貴。</p><p>除非還需要做其他的事情，否則只需使用 <code>count</code> 方法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>count = User.query.filter_by(acct_active=True).count()</span></span></code></pre></div><h3 id="只需要幾列時檢索整個模型" tabindex="-1">只需要幾列時檢索整個模型 <a class="header-anchor" href="#只需要幾列時檢索整個模型" aria-label="Permalink to “只需要幾列時檢索整個模型”">​</a></h3><p>在許多情況下，發出查詢時只需要幾列數據。SQLAlchemy 可以只獲取你想要的列，而不是返回整個模型實例。這不僅減少了發送的數據量，還避免了實例化整個對象。使用列數據的元組而不是模型可以快得多。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>result = User.query.all()</span></span>
<span class="line"><span>for user in result:</span></span>
<span class="line"><span>    print(user.name, user.email)</span></span></code></pre></div><p>反之，使用 <code>with_entities</code> 方法只選擇所需要的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>result = User.query.with_entities(User.name, User.email).all()</span></span>
<span class="line"><span>for (username, email) in result:</span></span>
<span class="line"><span>    print(username, email)</span></span></code></pre></div><h3 id="每次循環都更新一個對象" tabindex="-1">每次循環都更新一個對象 <a class="header-anchor" href="#每次循環都更新一個對象" aria-label="Permalink to “每次循環都更新一個對象”">​</a></h3><p>避免使用循環來單獨更新集合。雖然資料庫可以非常快地執行單個更新，但應用程序和資料庫服務器之間的往返時間將快速累加。通常，在合理的情況下爭取更少的查詢。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>for user in users_to_update:</span></span>
<span class="line"><span>  user.acct_active = True</span></span>
<span class="line"><span>  db.session.add(user)</span></span></code></pre></div><p>改用批量更新方法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>query = User.query.filter(user.id.in_([user.id for user in users_to_update]))</span></span>
<span class="line"><span>query.update({&quot;acct_active&quot;: True}, synchronize_session=False)</span></span></code></pre></div><h3 id="觸發級聯刪除" tabindex="-1">觸發級聯刪除 <a class="header-anchor" href="#觸發級聯刪除" aria-label="Permalink to “觸發級聯刪除”">​</a></h3><p>ORM 允許在模型關係上進行簡單的配置，但是有一些微妙的行為可能會令人吃驚。大多數資料庫通過外鍵和各種級聯選項維護關係完整性。SQLAlchemy 允許你使用外鍵和級聯選項定義模型，但是 ORM 具有自己的級聯邏輯，可以取代資料庫。</p><p>考慮以下模型：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>class Artist(Base):</span></span>
<span class="line"><span>    __tablename__ = &quot;artist&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    id = Column(Integer, primary_key=True)</span></span>
<span class="line"><span>    songs = relationship(&quot;Song&quot;, cascade=&quot;all, delete&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span></span></span>
<span class="line"><span>class Song(Base):</span></span>
<span class="line"><span>    __tablename__ = &quot;song&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    id = Column(Integer, primary_key=True)</span></span>
<span class="line"><span>    artist_id = Column(Integer, ForeignKey(&quot;artist.id&quot;, ondelete=&quot;CASCADE&quot;))</span></span></code></pre></div><p>刪除歌手將導致 ORM 在 <code>song</code> 表上發出 <code>delete</code> 查詢，從而防止由於外鍵導致的刪除操作。這種行為可能會成為複雜關係和大量記錄的瓶頸。</p><p>請包含 <code>passive_deletes</code> 選項，以確保讓資料庫來管理關係。但是，請確保你的資料庫具有此功能。例如，SQLite 默認情況下不管理外鍵。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>songs = relationship(&quot;Song&quot;, cascade  all, delete&quot;, passive_deletes=True)</span></span></code></pre></div><h3 id="當要使用貪婪加載時-應使用延遲加載" tabindex="-1">當要使用貪婪加載時，應使用延遲加載 <a class="header-anchor" href="#當要使用貪婪加載時-應使用延遲加載" aria-label="Permalink to “當要使用貪婪加載時，應使用延遲加載”">​</a></h3><p>延遲加載是 SQLAlchemy 處理關係的默認方法。從上一個例子構建來看，加載一個歌手時不會同時加載他或她的歌曲。這通常是一個好主意，但是如果總是需要加載某些關係，單獨的查詢可能會造成浪費。</p>`,26)),n("p",null,[s[7]||(s[7]=a("如果允許以延遲方式加載關係，像 ",-1)),i(e,{href:"https://marshmallow.readthedocs.io/en/stable/"},{default:t(()=>[...s[6]||(s[6]=[a("Marshmallow",-1)])]),_:1}),s[8]||(s[8]=a(" 這樣流行的序列化框架可以觸發級聯查詢。",-1))]),s[28]||(s[28]=l(`<p>有幾種方法可以控制此行為。最簡單的方法是通過 relationship 函數本身。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>songs = relationship(&quot;Song&quot;, lazy=&quot;joined&quot;, cascade=&quot;all, delete&quot;)</span></span></code></pre></div><p>這將導致一個左連接被添加到任何歌手的查詢中，因此，<code>songs</code> 集合將立即可用。儘管有更多數據返回給客户端，但往返次數可能會少得多。</p><p>SQLAlchemy 為無法採用這種綜合方法的情況提供了更細粒度的控制，可以使用 <code>joinedload()</code> 函數在每個查詢的基礎上切換連接的加載。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>from sqlalchemy.orm import joinedload</span></span>
<span class="line"><span></span></span>
<span class="line"><span>artists = Artist.query.options(joinedload(Artist.songs))</span></span>
<span class="line"><span>print(artists.songs) # Does not incur a roundtrip to load</span></span></code></pre></div><h3 id="使用-orm-進行批量記錄導入" tabindex="-1">使用 ORM 進行批量記錄導入 <a class="header-anchor" href="#使用-orm-進行批量記錄導入" aria-label="Permalink to “使用 ORM 進行批量記錄導入”">​</a></h3><p>導入成千上萬條記錄時，構建完整模型實例的開銷會成為主要瓶頸。想像一下，從一個文件中加載數千首歌曲記錄，其中每首歌曲都先被轉換為字典。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>for song in songs:</span></span>
<span class="line"><span>    db.session.add(Song(\`song))</span></span></code></pre></div><p>相反，繞過 ORM，只使用核心的 SQLAlchemy 參數綁定功能。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>batch = []</span></span>
<span class="line"><span>insert_stmt = Song.__table__.insert()</span></span>
<span class="line"><span>for song in songs:</span></span>
<span class="line"><span>    if len(batch) &amp;gt; 1000:</span></span>
<span class="line"><span>       db.session.execute(insert_stmt, batch)</span></span>
<span class="line"><span>       batch.clear()</span></span>
<span class="line"><span>    batch.append(song)</span></span>
<span class="line"><span>if batch:</span></span>
<span class="line"><span>    db.session.execute(insert_stmt, batch)</span></span></code></pre></div><p>請記住，此方法會自然而然地跳過你可能依賴的任何客户端 ORM 邏輯，例如基於 Python 的列默認值。儘管此方法比將對象加載為完整的模型實例要快，但是你的資料庫可能具有更快的批量加載方法。例如，PostgreSQL 的 <code>COPY</code> 命令為加載大量記錄提供了最佳性能。</p><h3 id="過早調用提交或刷新" tabindex="-1">過早調用提交或刷新 <a class="header-anchor" href="#過早調用提交或刷新" aria-label="Permalink to “過早調用提交或刷新”">​</a></h3><p>在很多情況下，你需要將子記錄與其父記錄相關聯，反之亦然。一種顯然的方法是刷新會話，以便為有問題的記錄分配一個 ID。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>artist = Artist(name=&quot;Bob Dylan&quot;)</span></span>
<span class="line"><span>song = Song(title=&quot;Mr. Tambourine Man&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>db.session.add(artist)</span></span>
<span class="line"><span>db.session.flush()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>song.artist_id = artist.id</span></span></code></pre></div><p>對於每個請求，多次提交或刷新通常是不必要的，也是不可取的。資料庫刷新涉及強制在資料庫服務器上進行磁盤寫入，在大多數情況下，客户端將阻塞，直到服務器確認已寫入數據為止。</p><p>SQLAlchemy 可以在幕後跟蹤關係和管理相關鍵。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>artist = Artist(name=&quot;Bob Dylan&quot;)</span></span>
<span class="line"><span>song = Song(title=&quot;Mr. Tambourine Man&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>artist.songs.append(song)</span></span></code></pre></div><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>我希望這一系列常見的陷阱可以幫助你避免這些問題，並使你的應用平穩運行。通常，在診斷性能問題時，測量是關鍵。大多數資料庫都提供性能診斷功能，可以幫助你定位問題，例如 PostgreSQL 的 <code>pg_stat_statements</code> 模組。</p><hr>`,20)),n("p",null,[s[10]||(s[10]=a("via: ",-1)),i(e,{href:"https://opensource.com/article/19/9/common-pitfalls-python"},{default:t(()=>[...s[9]||(s[9]=[a("https://opensource.com/article/19/9/common-pitfalls-python",-1)])]),_:1})]),n("p",null,[s[15]||(s[15]=a("作者：",-1)),i(e,{href:"https://opensource.com/users/zchtodd"},{default:t(()=>[...s[11]||(s[11]=[a("Zach Todd",-1)])]),_:1}),s[16]||(s[16]=a(" 選題：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[12]||(s[12]=[a("lujun9972",-1)])]),_:1}),s[17]||(s[17]=a(" 譯者：",-1)),i(e,{href:"https://github.com/MjSeven"},{default:t(()=>[...s[13]||(s[13]=[a("MjSeven",-1)])]),_:1}),s[18]||(s[18]=a(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[14]||(s[14]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[21]||(s[21]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[19]||(s[19]=[a("LCTT",-1)])]),_:1}),s[22]||(s[22]=a(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:t(()=>[...s[20]||(s[20]=[a("Linux中國",-1)])]),_:1}),s[23]||(s[23]=a(" 榮譽推出",-1))])])}const S=p(h,[["render",c]]);export{C as __pageData,S as default};
